  ('1', 'Item 01', 'дом'),
  ('2', 'Item 02', 'ДОМ'),
  ('3', 'Item 03', 'Дом'),
  ('4', 'Item 04', 'ÉCLAIR'),
  ('5', 'Item 05', 'дым');
DO $pp$
DECLARE got jsonb;
BEGIN
