  IF got IS DISTINCT FROM '{"StockItems":[{"StockItemID":1,"StockItemName":"Item 01"},{"StockItemID":2,"StockItemName":"Item 02"},{"StockItemID":3,"StockItemName":"Item 03"}]}'::jsonb THEN
    RAISE EXCEPTION 'agreed test failed (%): the JSON document differs: %', 'test 01 [A01 Tags: Cyrillic values differing only in case match a case-insensitive search (??? finds ??? and…', got;
  END IF;
END $pp$;
ROLLBACK;

